// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;
import "./IBEP20.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract BuyAdvert is Initializable{
    
    struct advert{
        address payable buyer;
        address payable seller;
        uint amount;
        address asset;
        bool closed;
    }

    address ADMIN_ADDRESS;

    event TokenTransfered(string advertId);
    event InitTrade(string advertId);
	event TradeClosed(string advertId);
	
    mapping(string=>advert) public BuyAdverts;

    function initialize(address _admin)public initializer{
        ADMIN_ADDRESS = _admin;
    }
    //Relating with buy ad created, message.sender owns the asset to be sold
    function createSellTrade(string memory _advertId,address payable _buyer,address _asset,uint _amount) external payable{
        require(_amount >0, "invalid token amount");
        require(BuyAdverts[_advertId].amount <= 0, "advert already exists");
        require(IBEP20(_asset).balanceOf(msg.sender) > _amount, "insuffifient balance");
        BuyAdverts[_advertId] = advert(_buyer,payable(msg.sender),_amount,_asset,false);
        IBEP20(_asset).transferFrom(payable(msg.sender),address(this),_amount);
		emit InitTrade(_advertId);
    }

    function setAdmin(address _admin) external{
        require(msg.sender == ADMIN_ADDRESS,"Unauthorized to make action");
        ADMIN_ADDRESS = _admin;
    }

    //When confirm payment is clicked by seller, asset owner recieving funds
    function transferAsset(string memory _advertId) external{
        advert storage ad = BuyAdverts[_advertId];
        require(msg.sender == ad.seller,"unauthorized to make this transaction");
        require(ad.closed == false, "contract closed");
        IBEP20(ad.asset).transfer(payable(ad.buyer),ad.amount);
        ad.closed = true;
		emit TokenTransfered(_advertId);
    }
	
    /**
        Admin cancels the trade and the seller is refunded
     */

    function adminCancel (string memory _advertId) external{
        require(msg.sender == ADMIN_ADDRESS,"unauthorized to make this transaction");
        advert storage _buyad = BuyAdverts[_advertId];
        require(_buyad.closed == false ,"advert closed");
        IBEP20(_buyad.asset).transfer(_buyad.seller, _buyad.amount);
        _buyad.closed = true;
    }

    /**
        Admin manually transfers token to buyer in terms of dispute
     */

    function adminTransfer (string memory _advertId) external{
        require(msg.sender == ADMIN_ADDRESS,"unauthorized to make this transaction");
        advert storage _buyad = BuyAdverts[_advertId];
        require(_buyad.closed ==  false,"advert closed");
        IBEP20(_buyad.asset).transfer(_buyad.buyer, _buyad.amount);
        _buyad.closed = true;
    }
    //Payer can decide to cancel trade
    function close(string memory _advertId) external{
        advert storage ad = BuyAdverts[_advertId];
        require(msg.sender == ad.buyer,"unauthorized to make this transaction");
        require(ad.closed == false, "contract closed already");
        IBEP20(ad.asset).transfer(payable(ad.seller),ad.amount);
        ad.closed = true;
		emit TradeClosed(_advertId);
    }
}
